mapper.select:
-- List rule releases without loading keyword content.
SELECT

FROM announcement_source_classification_rule_releases release


        release.release_status_code = #{releaseStatusCode}


ORDER BY release.version_no DESC
LIMIT #{limit}
OFFSET #{offset}

-- List keyword rules with canonical term and ordered synonyms. SELECT
FROM announcement_source_classification_keyword_rules rule INNER JOIN announcement_source_classification_rule_groups rule_group ON rule_group.id = rule.group_id INNER JOIN announcement_source_classification_rule_releases release ON release.id = rule_group.release_id INNER JOIN announcement_source_classification_keyword_terms canonical ON canonical.keyword_rule_id = rule.id AND canonical.group_id = rule_group.id AND canonical.term_type_code = 'CANONICAL' LEFT JOIN announcement_target_categories target_category ON target_category.id = rule_group.target_category_id LEFT JOIN announcement_support_types support_type ON support_type.id = rule_group.support_type_id WHERE release.id = #{releaseId}
AND rule_group.group_kind_code = #{groupKindCode}
AND rule_group.group_code = #{groupCode}
AND rule.strength_code = #{strengthCode}
AND EXISTS ( SELECT 1 FROM announcement_source_classification_keyword_terms mode_term WHERE mode_term.keyword_rule_id = rule.id AND mode_term.match_mode_code = #{matchModeCode} )
AND rule.is_enabled = #{enabled}
AND EXISTS ( SELECT 1 FROM announcement_source_classification_keyword_terms keyword_term WHERE keyword_term.keyword_rule_id = rule.id AND keyword_term.term_text ILIKE '%' || #{keyword} || '%' )
ORDER BY rule_group.sort_order, rule.sort_order, rule.rule_code LIMIT #{limit} OFFSET #{offset}

-- Count keyword rules for PageResponse with the same filters as the list.
SELECT count(1)
FROM announcement_source_classification_keyword_rules rule
INNER JOIN announcement_source_classification_rule_groups rule_group
        ON rule_group.id = rule.group_id
INNER JOIN announcement_source_classification_rule_releases release
        ON release.id = rule_group.release_id
WHERE release.id = #{releaseId}

    AND rule_group.group_kind_code = #{groupKindCode}


    AND rule_group.group_code = #{groupCode}


    AND rule.strength_code = #{strengthCode}


    AND EXISTS (
        SELECT 1
        FROM announcement_source_classification_keyword_terms mode_term
        WHERE mode_term.keyword_rule_id = rule.id
          AND mode_term.match_mode_code = #{matchModeCode}
    )


    AND rule.is_enabled = #{enabled}


    AND EXISTS (
        SELECT 1
        FROM announcement_source_classification_keyword_terms keyword_term
        WHERE keyword_term.keyword_rule_id = rule.id
          AND keyword_term.term_text ILIKE '%' || #{keyword} || '%'
    )

-- Reject normalized duplicates inside one group and match mode.
SELECT count(1)
FROM announcement_source_classification_keyword_terms term
WHERE term.group_id = #{groupId}
  AND term.match_mode_code = #{matchModeCode}
  AND term.normalized_term_text IN

      #{normalizedTerm}


    AND term.keyword_rule_id <> #{excludedRuleId}

mapper.delete:
-- Replace DRAFT terms only after the owning rule passed optimistic locking.
DELETE FROM announcement_source_classification_keyword_terms
WHERE keyword_rule_id = #{ruleId}

-- Physically delete only a service-validated, never-published DRAFT rule.
DELETE FROM announcement_source_classification_keyword_rules
WHERE id = #{ruleId}
  AND row_version = #{expectedVersion}

mapper.update:
-- Mark a locked DRAFT release changed after a child mutation.
UPDATE announcement_source_classification_rule_releases
SET row_version = row_version + 1,
    change_note = #{changeReason}
WHERE id = #{releaseId}
  AND release_status_code = 'DRAFT'

-- Reserve a DRAFT release mutation with release-level optimistic locking.
UPDATE announcement_source_classification_rule_releases
SET row_version = row_version + 1,
    change_note = #{changeReason}
WHERE id = #{releaseId}
  AND release_status_code = 'DRAFT'
  AND row_version = #{expectedVersion}
